import './test-bootstrap.mjs';
import fs from 'node:fs';
import path from 'node:path';
import { execSync } from 'node:child_process';
import pg from 'pg';

const { Pool } = pg;

// Ensure .env.local is loaded if process.env.DATABASE_URL is not set
if (!process.env.DATABASE_URL) {
  try {
    const envPath = path.resolve(process.cwd(), '.env.local');
    if (fs.existsSync(envPath)) {
      const content = fs.readFileSync(envPath, 'utf8');
      for (const line of content.split('\n')) {
        const trimmed = line.trim();
        if (trimmed && !trimmed.startsWith('#') && trimmed.includes('=')) {
          const idx = trimmed.indexOf('=');
          const key = trimmed.slice(0, idx).trim();
          const val = trimmed.slice(idx + 1).trim();
          if (!process.env[key]) {
            process.env[key] = val;
          }
        }
      }
    }
  } catch {}
}

function resolveDatabaseUrl() {
  if (process.env.DATABASE_URL && !process.env.DATABASE_URL.includes('127.0.0.1') && !process.env.DATABASE_URL.includes('localhost')) {
    return process.env.DATABASE_URL;
  }
  try {
    const wslIp = execSync('wsl -d Ubuntu -- hostname -I', { encoding: 'utf8' }).trim().split(/\s+/)[0];
    if (wslIp) {
      return `postgres://postgres:postgres@${wslIp}:5432/theroadproblem`;
    }
  } catch {}
  return process.env.DATABASE_URL || 'postgres://postgres:postgres@127.0.0.1:5432/theroadproblem';
}

const connectionStringRaw = resolveDatabaseUrl();
const isRemoteSsl = connectionStringRaw.includes('supabase') || connectionStringRaw.includes('sslmode=require');

let sslConfig = undefined;
let connectionString = connectionStringRaw;

if (isRemoteSsl) {
  connectionString = connectionStringRaw.replace(/[\?&]sslmode=[^&]+/, '');
  const certPath = path.resolve('certs/supabase-ca.pem');
  let caCert = undefined;
  if (fs.existsSync(certPath)) {
    caCert = fs.readFileSync(certPath, 'utf8');
  }
  sslConfig = {
    ca: caCert,
    rejectUnauthorized: true,
    checkServerIdentity: () => undefined,
  };
}

const pool = new Pool({
  connectionString,
  ssl: sslConfig
});

export async function importRoadsAndLocalities(client) {
  console.log('[seed] Seeding data sources...');
  const dsRes = await client.query(`
    INSERT INTO data_sources (name, publisher, base_uri, license, retrieval_method, update_frequency, terms_reviewed_at)
    VALUES 
      ('OpenStreetMap India Roads', 'OpenStreetMap Contributors', 'https://download.geofabrik.de/asia/india.html', 'ODbL 1.0', 'extract', 'weekly', NOW()),
      ('Open Government Data Transport', 'Ministry of Road Transport and Highways (MoRTH)', 'https://data.gov.in', 'GODL India', 'api', 'monthly', NOW()),
      ('Central Public Procurement Portal', 'National Informatics Centre (NIC)', 'https://eprocure.gov.in', 'GODL India', 'web', 'weekly', NOW())
    ON CONFLICT DO NOTHING
    RETURNING id;
  `);

  const osmSourceRes = await client.query(`SELECT id FROM data_sources WHERE name = 'OpenStreetMap India Roads' LIMIT 1;`);
  const osmSourceId = osmSourceRes.rows[0]?.id;

  console.log('[seed] Seeding localities...');
  const localities = JSON.parse(fs.readFileSync('scripts/data/sample_localities.json', 'utf8'));
  for (const loc of localities) {
    await client.query(`
      INSERT INTO localities (name, name_hi, state, district, type, center)
      VALUES ($1, $2, $3, $4, $5, ST_SetSRID(ST_MakePoint($6, $7), 4326))
      ON CONFLICT DO NOTHING;
    `, [loc.name, loc.name_hi, loc.state, loc.district, loc.type, loc.lon, loc.lat]);
  }

  console.log('[seed] Seeding road network with geometry & lineage...');
  const roads = JSON.parse(fs.readFileSync('scripts/data/sample_roads.json', 'utf8'));
  let insertedSegments = 0;

  for (const r of roads) {
    // 1. Upsert Road entity
    let roadId;
    const existingRoad = await client.query(`SELECT id FROM roads WHERE name = $1 AND state = $2 LIMIT 1;`, [r.road_name, r.state]);
    if (existingRoad.rows.length > 0) {
      roadId = existingRoad.rows[0].id;
    } else {
      const roadInsert = await client.query(`
        INSERT INTO roads (name, ref, road_class, authority_name, state, district, source_id)
        VALUES ($1, $2, $3, $4, $5, $6, $7)
        RETURNING id;
      `, [r.road_name, r.ref, r.road_class, r.authority_name, r.state, r.district, osmSourceId]);
      roadId = roadInsert.rows[0].id;
    }

    // 2. Process segments
    for (const seg of r.segments) {
      const lineStringWkt = `LINESTRING(${seg.coordinates.map((c) => `${c[0]} ${c[1]}`).join(', ')})`;

      // Check if segment already exists for these OSM IDs
      const existingSeg = await client.query(`
        SELECT id, length_m, version FROM road_segments 
        WHERE road_id = $1 AND $2 = ANY(osm_ids)
        LIMIT 1;
      `, [roadId, seg.osm_id]);

      if (existingSeg.rows.length > 0) {
        // Unchanged reimport: preserve UUID!
        continue;
      }

      // Insert new segment
      const segInsert = await client.query(`
        INSERT INTO road_segments (
          road_id, geom, chainage_from, chainage_to, state, district, osm_ids, length_m, version, is_active
        ) VALUES (
          $1,
          ST_SetSRID(ST_GeomFromText($2), 4326),
          $3, $4, $5, $6,
          ARRAY[$7::bigint],
          ST_Length(ST_SetSRID(ST_GeomFromText($2), 4326)::geography),
          1,
          TRUE
        )
        RETURNING id, length_m;
      `, [roadId, lineStringWkt, seg.chainage_from, seg.chainage_to, r.state, r.district, seg.osm_id]);

      const newSegId = segInsert.rows[0].id;
      insertedSegments++;

      // Record lineage
      await client.query(`
        INSERT INTO road_segment_lineage (segment_id, parent_segment_id, transition_type, reason, source_version)
        VALUES ($1, NULL, 'initial', 'Initial import from licensed OSM extract', 'osm-2026-10');
      `, [newSegId]);
    }
  }

  console.log(`[seed] Seed completed: ${insertedSegments} new road segments indexed.`);
}

async function main() {
  const client = await pool.connect();
  try {
    await importRoadsAndLocalities(client);
  } finally {
    client.release();
    await pool.end();
  }
}

if (process.argv[1]?.endsWith('seed.mjs')) {
  main().catch((err) => {
    console.error('[seed] Error running seed:', err);
    process.exit(1);
  });
}

import fs from 'node:fs';
import path from 'node:path';

// Never load .env.local here: that file contains the live database credential.
if (!process.env.TEST_DATABASE_URL && fs.existsSync('.env.test.local')) {
  for (const line of fs.readFileSync('.env.test.local','utf8').split(/\r?\n/)) {
    const m=/^TEST_DATABASE_URL=(.+)$/.exec(line.trim());
    if(m)process.env.TEST_DATABASE_URL=m[1].replace(/^['"]|['"]$/g,'');
  }
}
export function assertTestDatabase(value) {
  if(!value)throw new Error('TEST_DATABASE_URL is required; test writes are blocked.');
  const url=new URL(value),db=decodeURIComponent(url.pathname.slice(1));
  if(!/^theroadproblem(?:_[a-z0-9]+)*_test$/.test(db))throw new Error('Tests require a dedicated theroadproblem_*_test database.');
  const local=/^(localhost|127\.0\.0\.1|\[::1\]|10\.\d+\.\d+\.\d+|192\.168\.\d+\.\d+|172\.(1[6-9]|2\d|3[01])\.\d+\.\d+)$/.test(url.hostname);
  if(!local)throw new Error('Synthetic tests require a local/private test database, never a hosted production database.');
  return value;
}
export const testDatabaseUrl=assertTestDatabase(process.env.TEST_DATABASE_URL);
process.env.DATABASE_URL=testDatabaseUrl;
process.env.NODE_ENV='test';
process.env.LOCAL_PRIVATE_DIR=path.resolve('storage_data_test/private');
process.env.LOCAL_PUBLIC_DIR=path.resolve('storage_data_test/public');
for(const key of ['R2_ACCOUNT_ID','R2_ACCESS_KEY_ID','R2_SECRET_ACCESS_KEY','R2_PUBLIC_URL'])delete process.env[key];

import './test-bootstrap.mjs';
import crypto from 'node:crypto';
import assert from 'node:assert/strict';
import sharp from 'sharp';
import { pool } from '../src/db/client.ts';
import { processAndQuarantinePhoto } from '../src/lib/media.ts';
import { getStorageObject } from '../src/lib/storage.ts';

async function verifyCitizenReportFlow() {
  console.log('\n======================================================================');
  console.log(' VERIFYING CITIZEN FIELD REPORT & PHOTO INGESTION FLOW (R2 + POSTGIS)');
  console.log('======================================================================\n');

  const client = await pool.connect();
  await client.query('BEGIN');

  try {
    const fixturePoint=(await client.query(`SELECT id,ST_X(ST_LineInterpolatePoint(geom,0.5)) AS lon,ST_Y(ST_LineInterpolatePoint(geom,0.5)) AS lat FROM road_segments WHERE is_active ORDER BY id LIMIT 1`)).rows[0];
    assert.ok(fixturePoint,'Seeded test road required');
    const testLon=Number(fixturePoint.lon),testLat=Number(fixturePoint.lat);
    const reporterA = '99990000-0000-4000-8000-000000000002';
    const reporterB = '99990000-0000-4000-8000-000000000003';
    const reporterC = '99990000-0000-4000-8000-000000000004';
    const reporterD = '99990000-0000-4000-8000-000000000005';

    // Ensure test users exist
    await client.query(`
      INSERT INTO users (id, display_name, email_private, role, is_anonymous_public)
      VALUES 
        ($1, 'Citizen Reporter A', 'reporter.a@civic.test', 'citizen', TRUE),
        ($2, 'Citizen Reporter B', 'reporter.b@civic.test', 'citizen', TRUE),
        ($3, 'Citizen Reporter C', 'reporter.c@civic.test', 'citizen', TRUE),
        ($4, 'Citizen Reporter D', 'reporter.d@civic.test', 'citizen', TRUE)
      ON CONFLICT (id) DO NOTHING;
    `, [reporterA, reporterB, reporterC, reporterD]);

    // 1. Submit Citizen Report A on Outer Ring Road
    console.log('[Step 1] Submitting Ground Observation from Citizen A...');
    const idempotencyKeyA = `idemp-${Date.now()}`;
    const reportResA = await client.query(`
      SELECT submit_report_atomic(
        $1::uuid,
        ${testLon}::double precision,
        ${testLat}::double precision,
        'pothole'::text,
        'damaged'::text,
        'Deep waterlogged pothole on outer carriage lane near Ecospace'::text,
        NOW()::timestamptz,
        $2::text,
        NULL::uuid,
        '${fixturePoint.id}'::uuid
      ) as result;
    `, [reporterA, idempotencyKeyA]);

    const resultA = reportResA.rows[0].result;
    console.log('  Submission A Result:', resultA);
    assert.ok(resultA.report_id, 'Report ID must be created');
    assert.ok(resultA.incident_id, 'Incident ID must be created');
    assert.ok(resultA.road_segment_id, 'Must snap to nearest road segment via PostGIS');
    assert.ok(resultA.snap_distance_m >= 0, 'Snap distance must be non-negative');
    console.log(`  ✓ Report created (ID: ${resultA.report_id}) snapped to segment within ${resultA.snap_distance_m.toFixed(1)}m`);

    // 2. Photo Attachment Pipeline (EXIF stripping, Cloudflare R2 archival, and WebP normalization)
    console.log('\n[Step 2] Processing & Archiving Photographic Evidence to Storage...');
    const testImageBuffer = await sharp({
      create: {
        width: 1920,
        height: 1080,
        channels: 3,
        background: { r: 180, g: 60, b: 30 },
      },
    })
      .jpeg()
      .toBuffer();

    const mediaResult = await processAndQuarantinePhoto(testImageBuffer, resultA.report_id);
    console.log('  Media Result:', {
      mime_type: mediaResult.mime_type,
      original_bytes: mediaResult.original_bytes,
      derivative_bytes: mediaResult.derivative_bytes,
      width: mediaResult.width,
      height: mediaResult.height,
      quarantine_key: mediaResult.quarantine_key,
      derivative_key: mediaResult.derivative_key,
    });

    assert.equal(mediaResult.mime_type, 'image/webp');
    assert.ok(mediaResult.derivative_bytes < mediaResult.original_bytes, 'WebP derivative must be smaller than original');
    assert.ok(mediaResult.width <= 1600 && mediaResult.height <= 1600, 'Dimensions must be bounded within 1600px');

    // Verify presence in storage
    const derivativeFromStorage = await getStorageObject(mediaResult.derivative_key);
    assert.ok(derivativeFromStorage, 'Normalized derivative must exist in storage');

    // Register media in database
    await client.query(`
      INSERT INTO report_media (
        report_id, storage_key_quarantine, storage_key_derivative, mime_type, file_size_bytes, sha256,
        width, height, review_status, processed_at
      ) VALUES ($1, $2, $3, $4, $5, $6, $7, $8, 'approved', NOW());
    `, [
      resultA.report_id,
      mediaResult.quarantine_key,
      mediaResult.derivative_key,
      mediaResult.mime_type,
      mediaResult.derivative_bytes,
      mediaResult.sha256,
      mediaResult.width,
      mediaResult.height,
    ]);
    console.log(`  ✓ Photographic evidence normalized to WebP & recorded in report_media ledger`);

    // 3. Corroboration & Clustering Invariant (Citizen B reports 15m away)
    console.log('\n[Step 3] Submitting Corroborating Observation from Citizen B (15m away)...');
    const reportResB = await client.query(`
      SELECT submit_report_atomic(
        $1::uuid,
        ${testLon+0.00005}::double precision,
        ${testLat+0.00005}::double precision,
        'pothole'::text,
        'unsafe_workzone'::text,
        'Corroborating: Two wheeler skid observed here this morning'::text,
        NOW()::timestamptz,
        $2::text,
        $3::uuid,
        '${fixturePoint.id}'::uuid
      ) as result;
    `, [reporterB, `idemp-b-${Date.now()}`, resultA.incident_id]);

    const resultB = reportResB.rows[0].result;
    console.log('  Submission B Result:', resultB);
    assert.equal(resultB.incident_id, resultA.incident_id, 'Must cluster into existing incident within 30m');

    // Check reports attached to incident
    const reportsCountRes = await client.query(`
      SELECT COUNT(*) as count
      FROM reports
      WHERE incident_id = $1;
    `, [resultA.incident_id]);
    const reportCount = parseInt(reportsCountRes.rows[0].count, 10);
    assert.equal(reportCount, 2, 'Incident reports count must be 2');
    console.log(`  ✓ Clustered into incident ${resultA.incident_id}: attached reports = ${reportCount}`);

    // Test explicit multi-actor corroboration & anti-inflation invariants
    console.log('\n[Step 3b] Testing Multi-Actor Corroboration & Anti-Inflation Invariants...');

    // Negative Control: Reporter B (already an author) cannot self-corroborate
    let selfCorrobBlocked = false;
    await client.query('SAVEPOINT self_corrob_control');
    try {
      await client.query(`
        SELECT corroborate_incident_atomic(
          $1::uuid,
          $2::uuid,
          NOW()::timestamptz,
          'confirms_problem'::text,
          'Attempted self-corroboration'::text
        ) as result;
      `, [reporterB, resultA.incident_id]);
    } catch (err) {
      await client.query('ROLLBACK TO SAVEPOINT self_corrob_control');
      selfCorrobBlocked = err.message.includes('Anti-inflation invariant');
    }
    assert.ok(selfCorrobBlocked, 'Database must block author from self-corroborating');
    console.log('  ✓ Negative control passed: Anti-inflation prevented reporter self-inflation');

    // Positive Control: Independent Citizen C corroborates (1st confirmation)
    const corrobResC = await client.query(`
      SELECT corroborate_incident_atomic(
        $1::uuid,
        $2::uuid,
        NOW()::timestamptz,
        'confirms_problem'::text,
        'Citizen C confirms pothole unpatched'::text
      ) as result;
    `, [reporterC, resultA.incident_id]);
    assert.equal(corrobResC.rows[0].result.total_confirmations, 1);
    assert.equal(corrobResC.rows[0].result.verification_state, 'unverified');
    console.log('  ✓ 1st Confirmation (Citizen C): Incident remains unverified (threshold = 2 required)');

    // Positive Control: Independent Citizen D corroborates (2nd confirmation - hits threshold!)
    const corrobResD = await client.query(`
      SELECT corroborate_incident_atomic(
        $1::uuid,
        $2::uuid,
        NOW()::timestamptz,
        'confirms_problem'::text,
        'Citizen D confirms dangerous depth of crater'::text
      ) as result;
    `, [reporterD, resultA.incident_id]);
    assert.equal(corrobResD.rows[0].result.total_confirmations, 2);
    assert.equal(corrobResD.rows[0].result.verification_state, 'corroborated');
    console.log(`  ✓ 2nd Confirmation (Citizen D): Multi-actor threshold reached! Promoted to '${corrobResD.rows[0].result.verification_state}'`);

    const incidentCheck = await client.query(`
      SELECT id, verification_state, category
      FROM incidents
      WHERE id = $1;
    `, [resultA.incident_id]);
    assert.equal(incidentCheck.rows[0].verification_state, 'corroborated');

    // 4. Idempotency Check (Submitting identical key returns existing result)
    console.log('\n[Step 4] Verifying Replay Idempotency...');
    const replayRes = await client.query(`
      SELECT submit_report_atomic(
        $1::uuid,
        ${testLon}::double precision,
        ${testLat}::double precision,
        'pothole'::text,
        'damaged'::text,
        'Identical duplicate submission'::text,
        NOW()::timestamptz,
        $2::text,
        NULL::uuid,
        '${fixturePoint.id}'::uuid
      ) as result;
    `, [reporterA, idempotencyKeyA]);

    const replayResult = replayRes.rows[0].result;
    assert.equal(replayResult.report_id, resultA.report_id, 'Must return existing report ID');
    assert.equal(replayResult.is_idempotent_replay, true, 'is_idempotent_replay must be true');
    console.log('  ✓ Idempotency verified: Duplicate submission replayed cleanly without creating extra records.');

    console.log('\n======================================================================');
    console.log(' ALL VERIFICATION CHECKS PASSED: CITIZEN REPORT FLOW IS HEALTHY!');
    console.log('======================================================================\n');
  } finally {
    await client.query('ROLLBACK');
    client.release();
    await pool.end();
  }
}

verifyCitizenReportFlow()
  .then(() => process.exit(0))
  .catch((err) => {
    console.error('CITIZEN FLOW VERIFICATION FAILED:', err);
    process.exit(1);
  });

import './test-bootstrap.mjs';
import crypto from 'node:crypto';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { pool } from '../src/db/client.ts';
import { runTenderIngestion } from '../src/lib/ingestor/tender-ingestor.ts';
import { getStorageObject } from '../src/lib/storage.ts';

async function verifySingleIngestionFlow() {
  console.log('\n======================================================================');
  console.log(' VERIFYING SYNTHETIC TENDER FLOW IN ISOLATED TEST DATABASE');
  console.log('======================================================================\n');

  const client = await pool.connect();
  await client.query('BEGIN');

  try {
    // A single, realistic MoRTH / NHAI tender for Outer Ring Road resurfacing
    const testTender = {
      source_name: "MoRTH Central Public Procurement Portal (CPPP)",
      authority_name: "Bruhat Bengaluru Mahanagara Palike (BBMP)",
      tender_id: `VERIFY-FLOW-${Date.now()}`,
      contract_id: `CTR-VERIFY-${Date.now()}`,
      package_name: "Automated Flow Verification: Bellandur to Kadubeesanahalli Grade Separator",
      work_type: "Asphalt Overlay & Pavement Strengthening",
      official_status: "awarded",
      contract_value_inr: 325000000,
      start_date: "2026-04-01",
      target_completion_date: "2026-12-31",
      actual_completion_date: null,
      defect_liability_end_date: "2029-12-31",
      external_key: `EXT-FLOW-${Date.now()}`,
      source_uri: "https://eprocure.gov.in/eprocure/app?page=FrontEndTenderDetails&id=VERIFY-FLOW",
      district: "Bengaluru Urban",
      road_name_hint: "Outer Ring Road (ORR / NH-44)",
      road_ref: "ORR / NH-44",
      chainage_start_km: 0.0,
      chainage_end_km: 2.0,
      contractor: {
        legal_name: "Afcons Infrastructure Limited",
        normalized_name: "afcons-infrastructure-limited",
        vendor_identifier: "VND-AFCONS-9901",
        cin: "U45200MH1976PLC019335",
        gstin: "27AAACA1976G1Z2"
      }
    };

    console.log('[Step 1] Ingesting New Official Public Works Tender...');
    const run1 = await runTenderIngestion(client, [testTender]);
    console.log('  Result 1:', run1);

    assert.equal(run1.total_discovered, 1, 'Should discover 1 tender');
    assert.equal(run1.new_inserted, 1, 'Should insert exactly 1 new tender');
    assert.equal(run1.unchanged_skipped, 0, 'Should not skip on initial insertion');
    assert.equal(run1.r2_archived, 1, 'Should archive raw payload to Cloudflare R2');

    // Step 2: Verify R2 / Storage Archival
    console.log('\n[Step 2] Verifying Cloudflare R2 / Storage Archival...');
    const rawJsonStr = JSON.stringify(testTender);
    const checksum = crypto.createHash('sha256').update(rawJsonStr).digest('hex');
    const r2Key = `raw_sources/tenders/${testTender.external_key}_${checksum.slice(0, 8)}.json`;

    const archivedBytes = await getStorageObject(r2Key);
    assert.ok(archivedBytes, 'Raw document must exist in R2/storage');
    const parsedArchived = JSON.parse(archivedBytes.toString('utf8'));
    assert.equal(parsedArchived.tender_id, testTender.tender_id);
    console.log(`  ✓ Raw tender archived in storage at: ${r2Key} (${archivedBytes.length} bytes)`);

    // Step 3: Verify Supabase Database Records & Relational Lineage
    console.log('\n[Step 3] Verifying Database Ledgers in Supabase PostGIS...');

    // 3a. source_records
    const recCheck = await client.query(`
      SELECT sr.id, sr.external_key, sr.checksum_sha256, ds.name as data_source
      FROM source_records sr
      JOIN data_sources ds ON sr.source_id = ds.id
      WHERE sr.external_key = $1;
    `, [testTender.external_key]);
    assert.equal(recCheck.rows.length, 1, 'source_records must contain entry');
    assert.equal(recCheck.rows[0].checksum_sha256, checksum, 'SHA-256 fingerprint must match');
    console.log(`  ✓ Provenance recorded in source_records (ID: ${recCheck.rows[0].id}, SHA: ${checksum.slice(0, 16)}...)`);

    // 3b. contractors
    const conCheck = await client.query(`
      SELECT id, legal_name, cin, gstin FROM contractors WHERE normalized_name = $1;
    `, [testTender.contractor.normalized_name]);
    assert.equal(conCheck.rows.length, 1, 'Contractor must exist');
    assert.equal(conCheck.rows[0].cin, testTender.contractor.cin);
    console.log(`  ✓ Contractor registered: ${conCheck.rows[0].legal_name} (CIN: ${conCheck.rows[0].cin})`);

    // 3c. works and work_contractors
    const workCheck = await client.query(`
      SELECT w.id, w.tender_id, w.official_status, w.contract_value_inr, wc.confidence
      FROM works w
      JOIN work_contractors wc ON w.id = wc.work_id
      WHERE w.tender_id = $1;
    `, [testTender.tender_id]);
    assert.equal(workCheck.rows.length, 1, 'Work package must exist');
    assert.equal(workCheck.rows[0].official_status, 'awarded');
    assert.equal(workCheck.rows[0].confidence, 'verified_contract');
    console.log(`  ✓ Work package linked: ₹${(parseFloat(workCheck.rows[0].contract_value_inr) / 10000000).toFixed(2)} Cr [Status: ${workCheck.rows[0].official_status}]`);

    // 3d. PostGIS spatial linkage
    const segCheck = await client.query(`
      SELECT COUNT(*) as seg_count
      FROM work_segments
      WHERE work_id = $1;
    `, [workCheck.rows[0].id]);
    const segCount = parseInt(segCheck.rows[0].seg_count, 10);
    assert.ok(segCount > 0, 'Work must be spatially linked to road segments via PostGIS');
    console.log(`  ✓ Work snapped to ${segCount} road segment(s) along Outer Ring Road`);

    // 3e. Civic audit event in ledger
